import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        Arrays.sort(a);
        long largest = 0;
        for (int i = 0, j = 0; i < n; i = j) {
            while (j < n && a[j] == a[i]) j++;
            largest = Math.max(largest, j - i);
        }
        // The dominant kind can be cancelled at most n - f times; otherwise only parity remains.
        System.out.println(Math.max(2 * largest - n, n % 2));
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"sort"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(nextInt())
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	sort.Slice(a, func(i, j int) bool { return a[i] < a[j] })
	largest := 0
	for i, j := 0, 0; i < n; i = j {
		for j < n && a[j] == a[i] {
			j++
		}
		largest = max(largest, j-i)
	}
	// The dominant kind can be cancelled at most n - f times; otherwise only parity remains.
	fmt.Println(max(2*largest-n, n%2))
}
